// Turn the ESP32 batch into one Home Assistant sensor update per value.
// Only the NEWEST live record is used (older backlog records are skipped for HA).
const body = $input.first().json.body || $input.first().json;
const recs = (body.records || []).filter(r => r && r.values);
if (!recs.length) return [];

const live = recs.filter(r => r.mode !== 'demo');
const pick = (list) => list.reduce((a, b) => ((b.ts || 0) >= (a.ts || 0) ? b : a), list[0]);
const latest = pick(recs);

// key: [name, unit, device_class, icon]
const META = {
  rpm:          ['Engine RPM', 'rpm', null, 'mdi:engine'],
  speed:        ['Speed', 'km/h', 'speed', 'mdi:speedometer'],
  coolant:      ['Coolant Temp', '°C', 'temperature', 'mdi:coolant-temperature'],
  oil:          ['Oil Temp', '°C', 'temperature', 'mdi:oil-temperature'],
  intake:       ['Intake Temp', '°C', 'temperature', 'mdi:thermometer'],
  ambient:      ['Ambient Temp', '°C', 'temperature', 'mdi:thermometer'],
  voltage:      ['Battery Voltage', 'V', 'voltage', 'mdi:car-battery'],
  load:         ['Engine Load', '%', null, 'mdi:engine-outline'],
  throttle:     ['Throttle', '%', null, 'mdi:pedestrian'],
  rel_throttle: ['Rel. Throttle', '%', null, 'mdi:pedestrian'],
  pedal:        ['Accel Pedal', '%', null, 'mdi:car-brake-alert'],
  fuel:         ['Fuel Level', '%', null, 'mdi:gas-station'],
  fuel_rate:    ['Fuel Rate', 'L/h', null, 'mdi:fuel'],
  maf:          ['MAF Rate', 'g/s', null, 'mdi:air-filter'],
  map:          ['Intake MAP', 'kPa', 'pressure', 'mdi:gauge'],
  baro:         ['Baro Pressure', 'kPa', 'pressure', 'mdi:gauge'],
  fuel_press:   ['Fuel Pressure', 'kPa', 'pressure', 'mdi:gauge'],
  timing:       ['Timing Advance', '°', null, 'mdi:timer-cog-outline'],
  stft1:        ['Short Fuel Trim', '%', null, 'mdi:tune'],
  ltft1:        ['Long Fuel Trim', '%', null, 'mdi:tune'],
  runtime:      ['Run Time', 's', 'duration', 'mdi:timer-outline'],
  dist_mil:     ['Dist. with MIL', 'km', 'distance', 'mdi:map-marker-distance'],
  dist_clr:     ['Dist. since clear', 'km', 'distance', 'mdi:map-marker-distance'],
};

const items = [];
if (live.length) {
  const last = pick(live);
  for (const [k, v] of Object.entries(last.values)) {
    const m = META[k] || [k, null, null, 'mdi:car'];
    const attributes = { friendly_name: 'Car ' + m[0], icon: m[3], state_class: 'measurement' };
    if (m[1]) attributes.unit_of_measurement = m[1];
    if (m[2]) attributes.device_class = m[2];
    items.push({ json: { entity: 'sensor.car_' + k, state: Math.round(v * 100) / 100, attributes } });
  }
  items.push({ json: { entity: 'sensor.car_last_update',
    state: new Date(last.ts ? last.ts * 1000 : Date.now()).toISOString(),
    attributes: { friendly_name: 'Car last update', device_class: 'timestamp', icon: 'mdi:clock-outline' } } });
}
items.push({ json: { entity: 'sensor.car_obd_mode', state: latest.mode || 'unknown',
  attributes: { friendly_name: 'Car OBD mode', icon: 'mdi:car-connected', records_in_batch: recs.length } } });
return items;

// One Home Assistant notification per alert event from the ESP32.
const body = $input.first().json.body || $input.first().json;
return (body.records || []).map(a => {
  const val = (a.value !== undefined && a.value !== null) ? Number(a.value).toFixed(1) : '?';
  const title = a.event === 'triggered' ? '🚗⚠️ Car alert: ' + a.name : '🚗✅ Car alert cleared: ' + a.name;
  const message = a.name + ' = ' + val + ' ' + (a.unit || '') + '  (rule: ' + a.condition + ' ' + a.threshold + ')' + (a.mode === 'demo' ? '  [DEMO data]' : '');
  return { json: { title, message, notification_id: 'car_alert_' + (a.key || a.pid) } };
});
